CREATE TABLE IF NOT EXISTS public.mentoring_live_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), course_id uuid NOT NULL REFERENCES public.mentoring_courses(id) ON DELETE CASCADE, channel_id uuid NOT NULL REFERENCES public.mentoring_channels(id) ON DELETE CASCADE, host_user_id uuid NOT NULL, title text, is_recording boolean NOT NULL DEFAULT false, started_at timestamptz NOT NULL DEFAULT now(), ended_at timestamptz); ALTER TABLE public.mentoring_live_sessions ENABLE ROW LEVEL SECURITY; CREATE POLICY "Hub members view live sessions" ON public.mentoring_live_sessions FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'admin'::app_role) OR public.is_course_mentor(auth.uid(), course_id) OR public.is_mentoring_hub_member(auth.uid(), course_id)); CREATE POLICY "Mentors admins manage live sessions" ON public.mentoring_live_sessions FOR ALL TO authenticated USING (public.has_role(auth.uid(), 'admin'::app_role) OR public.is_course_mentor(auth.uid(), course_id)) WITH CHECK (public.has_role(auth.uid(), 'admin'::app_role) OR public.is_course_mentor(auth.uid(), course_id));